//! fixtures/merkle-vectors.json (generated by packages/sdk/scripts/gen-rewards-fixtures.ts)
//! against the program's Merkle code: the TS tree builder and the on-chain verifier agree on
//! every leaf, node, root and proof, and every scenario round is internally consistent.

use anchor_lang::prelude::Pubkey;
use deep_rewards::merkle::{leaf_hash, node_hash, verify};
use serde_json::Value;
use std::str::FromStr;

fn fixtures() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/merkle-vectors.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("read merkle-vectors.json"))
        .expect("json")
}

fn pk(v: &Value) -> Pubkey {
    Pubkey::from_str(v.as_str().unwrap()).unwrap()
}

fn h32(v: &Value) -> [u8; 32] {
    let s = v.as_str().unwrap();
    let mut out = [0u8; 32];
    for (i, b) in out.iter_mut().enumerate() {
        *b = u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).unwrap();
    }
    out
}

fn u(v: &Value) -> u64 {
    v.as_str().unwrap().parse().unwrap()
}

#[test]
fn program_id_matches() {
    assert_eq!(pk(&fixtures()["programId"]), deep_rewards::ID);
}

#[test]
fn leaf_and_node_hashes() {
    let f = fixtures();
    let leaves = f["hashing"]["leaves"].as_array().unwrap();
    assert!(leaves.len() >= 4);
    for l in leaves {
        assert_eq!(
            leaf_hash(&pk(&l["distributor"]), &pk(&l["claimant"]), u(&l["amount"])),
            h32(&l["leaf"])
        );
    }
    for n in f["hashing"]["nodes"].as_array().unwrap() {
        assert_eq!(node_hash(&h32(&n["a"]), &h32(&n["b"])), h32(&n["node"]));
        assert_eq!(node_hash(&h32(&n["b"]), &h32(&n["a"])), h32(&n["node"]));
    }
}

#[test]
fn every_tree_proof_verifies_on_chain_code() {
    let f = fixtures();
    let mut checked = 0;
    for t in f["trees"].as_array().unwrap() {
        let d = pk(&t["distributor"]);
        let root = h32(&t["root"]);
        let mut sum = 0u64;
        for l in t["leaves"].as_array().unwrap() {
            let leaf = leaf_hash(&d, &pk(&l["claimant"]), u(&l["cumulative"]));
            assert_eq!(leaf, h32(&l["leaf"]));
            let proof: Vec<[u8; 32]> = l["proof"].as_array().unwrap().iter().map(h32).collect();
            assert!(verify(&proof, &root, leaf));
            // wrong amount / wrong distributor never verify
            assert!(!verify(
                &proof,
                &root,
                leaf_hash(&d, &pk(&l["claimant"]), u(&l["cumulative"]) + 1)
            ));
            assert!(!verify(
                &proof,
                &root,
                leaf_hash(&Pubkey::default(), &pk(&l["claimant"]), u(&l["cumulative"]))
            ));
            sum += u(&l["cumulative"]);
            checked += 1;
        }
        assert_eq!(sum, u(&t["maxTotalClaim"]));
    }
    assert_eq!(checked, 1 + 2 + 3 + 5 + 8 + 17);
}

#[test]
fn scenario_rounds_are_consistent() {
    let f = fixtures();
    for (_, s) in f["scenarios"].as_object().unwrap() {
        let d = pk(&s["distributor"]);
        let mut prev: std::collections::HashMap<String, u64> = Default::default();
        let mut deposited = 0u64;
        let mut prev_max = 0u64;
        for r in s["rounds"].as_array().unwrap() {
            deposited += u(&r["deposit"]);
            let pool = u(&r["pool"]);
            assert_eq!(pool, deposited - prev_max, "pool = deposits − previous total");
            assert_eq!(u(&r["allocatedTotal"]) + u(&r["dust"]), pool);
            let root = h32(&r["root"]);
            let mut sum = 0u64;
            for l in r["leaves"].as_array().unwrap() {
                let c = u(&l["cumulative"]);
                let who = l["claimant"].as_str().unwrap().to_string();
                // cumulative never decreases
                assert!(c >= *prev.get(&who).unwrap_or(&0));
                let proof: Vec<[u8; 32]> =
                    l["proof"].as_array().unwrap().iter().map(h32).collect();
                assert!(verify(&proof, &root, leaf_hash(&d, &pk(&l["claimant"]), c)));
                sum += c;
                prev.insert(who, c);
            }
            assert_eq!(sum, u(&r["maxTotalClaim"]));
            // every wallet from earlier rounds is still in the tree
            assert_eq!(prev.len(), r["leaves"].as_array().unwrap().len());
            // excluded owners never get a leaf
            for (owner, _) in r["excluded"].as_object().unwrap() {
                assert!(r["weights"].get(owner).is_none());
                assert!(
                    r["allocated"].get(owner).is_none(),
                    "excluded {owner} was allocated"
                );
            }
            prev_max = sum;
        }
    }
}
